class Solution:
    def minimumCardPickup(self, cards: List[int]) -> int:
        last = {}
        ans = float('inf')
        for i, c in enumerate(cards):
            if c in last:
                ans = min(ans, i - last[c] + 1)
            last[c] = i
        return ans if ans != float('inf') else -1

