class Solution {
public:
    int minimumCardPickup(vector<int>& cards) {
        unordered_map<int, int> last;
        int ans = INT_MAX;
        for (int i = 0; i < cards.size(); i++) {
            auto it = last.find(cards[i]);
            if (it != last.end()) ans = min(ans, i - it->second + 1);
            last[cards[i]] = i;
        }
        return ans == INT_MAX ? -1 : ans;
    }
};

